global using Microsoft.EntityFrameworkCore;
public sealed record Address(string Street, string City);
public sealed record Label(Guid OrderId, string Name, string Street, string City);
public sealed class OrderRow
{
    public Guid Id { get; set; }
    public string Status { get; set; } = "";
    public DateTime? ShippedAt { get; set; }
    public string CustomerName { get; set; } = "";
    public string Street { get; set; } = "";
    public string City { get; set; } = "";
}
public sealed class Shipment(Guid orderId, string recipient, Address shipTo)
{
    public Guid OrderId { get; } = orderId;
    public string Recipient { get; } = recipient;
    public Address ShipTo { get; } = shipTo;
    public DateTime? ShippedAt { get; set; }
}
public sealed class ShopDb(DbContextOptions<ShopDb> options) : DbContext(options)
{
    public DbSet<OrderRow> Orders => Set<OrderRow>();
}
public sealed class ShippingDb(DbContextOptions<ShippingDb> options) : DbContext(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();
}
